<?php

declare(strict_types=1);

namespace MaikSchneider\SolrShield\EventListener;

use ApacheSolrForTypo3\Solr\Event\Routing\AfterUriIsProcessedEvent;
use MaikSchneider\SolrShield\Service\TokenService;
use TYPO3\CMS\Core\Site\Entity\Site;

/**
 * Encodes tx_solr parameters in every URI generated by the Solr extension
 * (filter links, pagination, sorting, etc.) into a signed obfuscation payload.
 *
 * The resulting URL carries a single `_ss=<base64-payload>` parameter instead
 * of the raw `tx_solr[...]` parameters. SolrShieldMiddleware decodes it on
 * the next request.
 */
final readonly class AfterUriIsProcessedEventListener
{
    public function __construct(
        private TokenService $tokenService,
    ) {
    }

    public function __invoke(AfterUriIsProcessedEvent $event): void
    {
        if (!$this->isObfuscationEnabled()) {
            return;
        }

        $uri = $event->getUri();
        $queryString = $uri->getQuery();

        if ($queryString === '') {
            return;
        }

        parse_str($queryString, $allParams);

        $txSolrParams = array_filter(
            $allParams,
            static fn (int|string $key): bool => str_starts_with((string)$key, 'tx_solr'),
            ARRAY_FILTER_USE_KEY
        );

        if ($txSolrParams === []) {
            return;
        }

        $otherParams = array_filter(
            $allParams,
            static fn (int|string $key): bool => !str_starts_with((string)$key, 'tx_solr'),
            ARRAY_FILTER_USE_KEY
        );

        // Single signed parameter: p = tx_solr query string, s = HMAC token
        $payload = base64_encode((string)json_encode([
            'p' => http_build_query($txSolrParams),
            's' => $this->tokenService->generateToken(),
        ]));

        $newParams = array_merge($otherParams, ['_ss' => $payload]);

        $event->replaceUri($uri->withQuery(http_build_query($newParams)));
    }

    private function isObfuscationEnabled(): bool
    {
        return (bool)$this->readSiteSetting('solrShield.uriObfuscation.enabled', true);
    }

    private function readSiteSetting(string $key, mixed $default): mixed
    {
        $request = $GLOBALS['TYPO3_REQUEST'] ?? null;
        if ($request === null) {
            return $default;
        }
        $site = $request->getAttribute('site');
        if (!$site instanceof Site) {
            return $default;
        }
        return $site->getSettings()->get($key, $default);
    }
}
